-- Synced units, themes, subthemes, and content blocks mapped to static IDs in unitCurriculum.ts
CREATE TABLE IF NOT EXISTS custom_units (id TEXT PRIMARY KEY, subject_id TEXT NOT NULL, grade_id TEXT NOT NULL, content TEXT NOT NULL, updated_at TEXT NOT NULL);
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-401', 'naturales', '4to', '{"id":"nat-401","name":"La Célula y los Seres Vivos","themes":[{"id":"t-nat-401-1","name":"La Célula","subthemes":[{"id":"st-nat-401-1-1","name":"Estructura celular: membrana, citoplasma y núcleo"},{"id":"st-nat-401-1-2","name":"Células animales y vegetales"},{"id":"st-nat-401-1-3","name":"Clasificación de los seres vivos en los cinco reinos"}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-401-block-1","themes":["La Célula"],"conceptual":"Ciencias de la Vida \n–\tLa biodiversidad de los seres vivos y su organización celular.\n–\tLas plantas: endémicas y nativas.\n–\tLos animales: endémicos y nativos.\n–\tReproducción: asexual y sexual.\n–\tCaracteres hereditarios.\n–\tNutrición en plantas y animales.\nInteracción y movimiento – Movimiento en plantas.","procedural":"Ciencias de la Vida\n–\tDescripción e interpretación de las células vegetal y animal. \n–\tIndagación: seres vivos unicelulares y multicelulares. Procedimiento: formulación de preguntas, búsqueda de información, planteamiento de hipótesis, experimentación, interpretación, selección de la información, comparación, inferencia, argumentación, dibujos, reporte en diario de laboratorio.\n–\tObservación de las partes de las plantas: raíz, tallo, hoja, flor, fruto, semilla. Procedimiento: exploración de plantas de su entorno y construcción de modelos.\n–\tExploración del cuerpo de los animales de su entorno. Procedimiento: uso de material didáctico (atlas, láminas), instrumentos (microscopio, estereoscopio), audiovisuales (videos, películas, documentales), construcción de modelos, comparación, clasificación, descripción, comunicación oral y escrita, dibujos.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tExperimentación (guiada) sobre el proceso de fotosíntesis en las plantas. Procedimiento: recolección de información, formulación de preguntas, planteamiento de hipótesis, experimentación, registro de información, comparación, inferencia, argumentación, discusión, comunicación de resultados, redacción y exposición.\n–\tIndagación sobre la biodiversidad autóctona, flora y fauna (nativa y endémica), de la isla de Santo Domingo. Procedimientos: observación, recolección de información, construcción de modelos, clasificación, descripción, elaboración e interpretación de mapas temáticos, interpretación, comentarios, exposición.\n–\tIndagación sobre las enfermedades de las plantas y animales que habitan en su entorno inmediato o localidad. Procedimiento: preguntas de investigación, planificación, búsqueda de información, diseño, planteamiento de hipótesis, entrevistas, experimentación, toma de datos, interpretación, selección de información, inferencia, redacción y exposición.","attitudinal":"–\tValoración y protección de la biodiversidad, así como de los entornos local, regional y global.\n–\tManifestación de cooperación e interés ante la situación de salubridad de su entorno, contribuyendo al mantenimiento de un espacio adecuado para una vida de calidad."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.189Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-402', 'naturales', '4to', '{"id":"nat-402","name":"Nutrición y Sistemas del Cuerpo Humano","themes":[{"id":"t-nat-402-1","name":"Alimentación y Digestión","subthemes":[{"id":"st-nat-402-1-1","name":"Grupos de alimentos y nutrientes esenciales para el crecimiento"},{"id":"st-nat-402-1-2","name":"El sistema digestivo: órganos y su cuidado"},{"id":"st-nat-402-1-3","name":"Sistema osteomuscular y hábitos de postura"}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-402-block-1","themes":["Alimentación y Digestión"],"conceptual":"–\tReproducción: asexual y sexual.\nEnergía y conservación\n–\tNutrición en plantas y animales.\n–\tLa fotosíntesis.\n–\tFlujo de energía en ecosistemas.\n–\tLos ecosistemas y los recursos naturales.\nSalud y ser humano\n–\tCuidado del cuerpo humano.\n–\tEnfermedades tropicales y virales (transmitidas por vectores).","procedural":"–\tExploración del cuerpo de los animales de su entorno. Procedimiento: uso de material didáctico (atlas, láminas), instrumentos (microscopio, estereoscopio), audiovisuales (videos, películas, documentales), construcción de modelos, comparación, clasificación, descripción, comunicación oral y escrita, dibujos.\n–\tCaracterización del cuerpo, órganos y sistemas de la especie humana (digestivo, circulatorio, respiratorio, excretor, nervioso y reproductor). Procedimiento: uso de material didáctico (láminas, atlas, modelos), audiovisual (videos, películas, documentales) y aparatos (microscopio, estereoscopio), construcción de modelos, comparación, clasificación, descripción, inferencia, comunicación oral y escrita, dibujos.\n–\tIndagación sobre los cambios biológicos que ocurren durante la pubertad. Procedimiento: exploración, utilización de material didáctico (láminas, libros, atlas), audiovisuales (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tExperimentación (guiada) sobre el proceso de fotosíntesis en las plantas. Procedimiento: recolección de información, formulación de preguntas, planteamiento de hipótesis, experimentación, registro de información, comparación, inferencia, argumentación, discusión, comunicación de resultados, redacción y exposición.\n–\tIndagación sobre las enfermedades de las plantas y animales que habitan en su entorno inmediato o localidad. Procedimiento: preguntas de investigación, planificación, búsqueda de información, diseño, planteamiento de hipótesis, entrevistas, experimentación, toma de datos, interpretación, selección de información, inferencia, redacción y exposición.","attitudinal":"–\tMotivación e interés en el uso sostenible de los recursos, asumiendo una actitud de ahorro e integrándose al reúso, reducción y reciclaje de materiales.\n–\tValoración y protección de la biodiversidad, así como de los entornos local, regional y global.\n–\tManifestación de cooperación e interés ante la situación de salubridad de su entorno, contribuyendo al mantenimiento de un espacio adecuado para una vida de calidad.\n–\tDemostración de interés por aprender sobre el funcionamiento y la salud de los sistemas del cuerpo humano.\n–\tParticipación en los proyectos, en la toma de decisiones y en la búsqueda de soluciones a situaciones problemáticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.191Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-403', 'naturales', '4to', '{"id":"nat-403","name":"Materia, Energía y Máquinas","themes":[{"id":"t-nat-403-1","name":"Propiedades de la Materia y Energía","subthemes":[{"id":"st-nat-403-1-1","name":"Propiedades físicas de la materia y estados de agregación"},{"id":"st-nat-403-1-2","name":"La luz y el sonido: características y propagación"},{"id":"st-nat-403-1-3","name":"Uso de máquinas simples en la vida diaria"}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-403-block-1","themes":["Propiedades de la Materia y Energía"],"conceptual":"Materia y sus propiedades\nEnergía y conservación\n–\tFlujo de energía en ecosistemas.","procedural":"Procedimiento: uso de modelos, material audiovisual (video educativo, película, documental, atlas, lámina), utilización de instrumentos (microscopio, estereoscopio), observación, dibujos, comparación, conclusión, exposición de resultados.\n–\tObservación de raíces, hojas y flores de su entorno. Procedimiento: utilización de recursos del medio, materiales didácticos y audiovisuales, recolección de información, comparación, clasificación, descripción, dibujos, comunicación de los resultados y reporte diario de laboratorio.\n–\tExploración del cuerpo de los animales de su entorno. Procedimiento: uso de material didáctico (atlas, láminas), instrumentos (microscopio, estereoscopio), audiovisuales (videos, películas, documentales), construcción de modelos, comparación, clasificación, descripción, comunicación oral y escrita, dibujos.\n–\tCaracterización del cuerpo, órganos y sistemas de la especie humana (digestivo, circulatorio, respiratorio, excretor, nervioso y reproductor). Procedimiento: uso de material didáctico (láminas, atlas, modelos), audiovisual (videos, películas, documentales) y aparatos (microscopio, estereoscopio), construcción de modelos, comparación, clasificación, descripción, inferencia, comunicación oral y escrita, dibujos.\n–\tIndagación sobre los cambios biológicos que ocurren durante la pubertad. Procedimiento: exploración, utilización de material didáctico (láminas, libros, atlas), audiovisuales (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.\n–\tIndagación sobre la reproducción sexual y asexual en los seres vivos. Procedimiento: formulación de preguntas, búsqueda de información, utilización de material didáctico (láminas, libros, atlas) y audiovisual (videos, películas, documentales), recolección de información, comparación, descripción, inferencia, comunicación de resultados.","attitudinal":"–\tMotivación e interés en el uso sostenible de los recursos, asumiendo una actitud de ahorro e integrándose al reúso, reducción y reciclaje de materiales.\n–\tValoración y protección de la biodiversidad, así como de los entornos local, regional y global.\n–\tManifestación de cooperación e interés ante la situación de salubridad de su entorno, contribuyendo al mantenimiento de un espacio adecuado para una vida de calidad.\n–\tDemostración de interés por aprender sobre el funcionamiento y la salud de los sistemas del cuerpo humano.\n–\tParticipación en los proyectos, en la toma de decisiones y en la búsqueda de soluciones a situaciones problemáticas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.191Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-404', 'naturales', '4to', '{"id":"nat-404","name":"Estructura de la Tierra y sus Recursos","themes":[{"id":"t-nat-404-1","name":"Capas de la Tierra y el Entorno","subthemes":[{"id":"st-nat-404-1-1","name":"Capas internas y externas de la Tierra"},{"id":"st-nat-404-1-2","name":"Rocas y minerales de la República Dominicana"},{"id":"st-nat-404-1-3","name":"Cuidado y conservación del agua y el aire"}]}],"grade_levels":["4to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-404-block-1","themes":["Capas de la Tierra y el Entorno"],"conceptual":"\"Ciencias de la tierra y el universo\"\n–\tComposición física del planeta Tierra.\n–\tFenómenos naturales. Sismos.\n–\tEl Sol: fuente de energía.\n–\tSistema Solar: Sol, planetas, satélites, luna, cometas.\n–\tMovimiento y trayectoria de los planetas del Sistema Solar.","procedural":"\"Ciencias de la tierra y el universo\"\n–\tDescripción y comparación entre el manto y la corteza del planeta Tierra. Comunicación por medio de dibujos y esquemas.\n–\tObservación, descripción y comparación entre rocas y minerales, clasificándolos de acuerdo a sus propiedades y características físicas.\n–\tAnálisis y discusión sobre sismos y energía, reconociendo que los sismos liberan grandes cantidades de energía capaces de hacer daño a estructuras y seres vivos.\n–\tExperimentación guiada sobre el Sol como fuente de energía. Análisis a través de fuentes tecnológicas diferentes, y comunicación de resultados.\n–\tObservación, descripción y comparación entre la Luna, el Sol, planetas, estrellas y cometas. Comunicación por medio de dibujos y esquemas.\n–\tAnálisis y discusión (comparación, clasificación, descripción) sobre los planetas, la Luna y otros cuerpos del Sistema Solar, y sus movimientos y trayectorias alrededor del Sol. Comunicación por medio de dibujos, esquemas, observación de videos.","attitudinal":"–\tMotivación e interés por aprender sobre sí mismo, sobre su entorno y por mantener una convivencia sana, mostrando solidaridad, respeto y colaboración con los demás.\n–\tAdopción de medidas de cuidado y utilización sostenible de los recursos naturales.\n–\tDemostración de interés por seguir instrucciones de seguridad y cuidado ante la manifestación de riesgos asociados a fenómenos naturales (sismos)\n–\tValoración de la Luna y el Sol y los beneficios para la vida en el planeta Tierra."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.192Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-501', 'naturales', '5to', '{"id":"nat-501","name":"Ecosistemas y Biodiversidad","themes":[{"id":"t-nat-501-1","name":"Ecosistemas Dominicanos","subthemes":[{"id":"st-nat-501-1-1","name":"Tipos de ecosistemas terrestres y acuáticos en la isla"},{"id":"st-nat-501-1-2","name":"Flora y fauna endémica y nativa amenazada"},{"id":"st-nat-501-1-3","name":"Áreas protegidas de la República Dominicana"}]}],"grade_levels":["5to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-501-block-1","themes":["Ecosistemas Dominicanos"],"conceptual":"“Ciencias de la Vida “\n“Materia y sus propiedades”\n– Los fósiles.\n–\tEvolución de las especies.\n–\tLa Española y su historia fósil.\n“Interacción y movimiento”\n– Impulso nervioso.\n“Sistema y mecanismo”\n–\tMedioambiente: Áreas protegidas.\n“Salud y ser humano”\n–\tEnfermedades: bacterias infectocontagiosas.\n–\tSistemas: muscular, óseo, nervioso y reproductor.\n–\tReproducción y fecundación.\n ","procedural":"\"Ciencias de la Vida\"\n \n–\tIndagación sobre los tipos de fósiles y sus características. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.\n–\tIndagación acerca de científicos que han hecho aportes sobre la teoría de la evolución. Búsqueda de información, lectura y comentario, conclusión y exposición de los resultados.\n–\tObservación, descripción, comparación y discusión acerca de fósiles de la República Dominicana y sus características.\n–\tIndagación sobre la evolución de la vida. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, análisis, discusión y comunicación.\n–\tObservación, análisis y discusión de la biogeografía de los seres vivos en el planeta.\n–\tExperimentación (guiada) con rocas o resinas con fósiles. Procedimiento: descripción, comparación, análisis, discusión y comunicación.\n–\tIndagación sobre las estructuras y funciones de los sistemas y aparatos en animales y en el ser humano. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación (guiada), análisis, discusión y comunicación.\n–\tAnálisis de características de la transmisión del impulso nervioso.\n–\tEnfermedades de los sistemas muscular, óseo y nervioso. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tInvestigación sobre los cambios morfológicos y fisiológicos que ocurren en la pubertad. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tIndagación sobre la situación de las Áreas protegidas de la República Dominicana. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, uso de mapas, planificación y diseño, ejecución, conclusión y exposición.\n \n–\tElaboración de un listado de vacunas contra enfermedades infecciosas. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, planificación y diseño, ejecución, conclusión y exposición.\n–\tEnfermedades infecciosas causadas por bacterias y hongos. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.\n \n ","attitudinal":"–\tMotivación de seguir los procedimientos propios de la investigación sistemática para dar respuesta científica a sus preguntas y comprobar sus ideas.\n–\tValoración y cuidado de su salud, su bienestar y los de las demás personas.\n–\tAdopción de responsabilidad, solidaridad, curiosidad y creatividad en la búsqueda de soluciones a problemas.\n–\tValoración de los recursos naturales y de su uso sostenible.\n–\tManifestación de interés en la obtención de informaciones sobre eventos naturales, medidas de prevención, recomendaciones y rutas de seguridad.\n–\tMotivación respecto a la colaboración y trabajo en equipo en las actividades del ámbito escolar, familiar y comunitario.\n–\tManifestación de curiosidad, creatividad, objetividad.\n–\tComunicación de sus ideas, seguimiento de procedimientos, trabajo individual y colaborativo.\n–\tRespeto a las ideas y diferencias de los demás, solidaridad.\n–\tUtilización sostenible de los recursos materiales y tecnológicos de que dispone.\n–\tDemostración de interés por conocer sobre las propiedades y características de la materia y la energía, así como por utilizar herramientas y construir máquinas comprendiendo sus mecanismos y funcionamiento.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.193Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-502', 'naturales', '5to', '{"id":"nat-502","name":"Sistemas Corporales y Nutrición Compleja","themes":[{"id":"t-nat-502-1","name":"Sistemas de Relación y Nutrición","subthemes":[{"id":"st-nat-502-1-1","name":"Sistemas circulatorio, respiratorio y excretor"},{"id":"st-nat-502-1-2","name":"Elaboración de una dieta balanceada"},{"id":"st-nat-502-1-3","name":"Efectos del alcohol y tabaco en la salud humana"}]}],"grade_levels":["5to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-502-block-1","themes":["Sistemas de Relación y Nutrición"],"conceptual":"– Impulso nervioso.\n“Salud y ser humano”\n–\tEnfermedades: bacterias infectocontagiosas.\n–\tSistemas: muscular, óseo, nervioso y reproductor.\n–\tReproducción y fecundación.","procedural":"–\tAnálisis de características de la transmisión del impulso nervioso.\n–\tEnfermedades de los sistemas muscular, óseo y nervioso. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tInvestigación sobre los cambios morfológicos y fisiológicos que ocurren en la pubertad. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tElaboración de un listado de vacunas contra enfermedades infecciosas. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, planificación y diseño, ejecución, conclusión y exposición.\n–\tEnfermedades infecciosas causadas por bacterias y hongos. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.","attitudinal":"–\tValoración y cuidado de su salud, su bienestar y los de las demás personas.\n–\tDemostración de interés por conocer sobre las propiedades y características de la materia y la energía, así como por utilizar herramientas y construir máquinas comprendiendo sus mecanismos y funcionamiento."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.193Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('nat-503', 'naturales', '5to', '{"id":"nat-503","name":"Materia y Cambios de la Energía","themes":[{"id":"t-nat-503-1","name":"Electricidad y Magnetismo","subthemes":[{"id":"st-nat-503-1-1","name":"Energía térmica y transmisión del calor"},{"id":"st-nat-503-1-2","name":"Circuitos eléctricos sencillos y conductores"},{"id":"st-nat-503-1-3","name":"Fuentes de energía renovables y no renovables"}]}],"grade_levels":["5to"],"subjectId":"naturales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"nat-503-block-1","themes":["Electricidad y Magnetismo"],"conceptual":"“Ciencias de la Vida “\n“Materia y sus propiedades”\n– Los fósiles.\n–\tEvolución de las especies.\n–\tLa Española y su historia fósil.\n“Interacción y movimiento”\n– Impulso nervioso.\n“Sistema y mecanismo”\n–\tMedioambiente: Áreas protegidas.\n“Salud y ser humano”\n–\tEnfermedades: bacterias infectocontagiosas.\n–\tSistemas: muscular, óseo, nervioso y reproductor.\n–\tReproducción y fecundación.\n ","procedural":"\"Ciencias de la Vida\"\n \n–\tIndagación sobre los tipos de fósiles y sus características. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.\n–\tIndagación acerca de científicos que han hecho aportes sobre la teoría de la evolución. Búsqueda de información, lectura y comentario, conclusión y exposición de los resultados.\n–\tObservación, descripción, comparación y discusión acerca de fósiles de la República Dominicana y sus características.\n–\tIndagación sobre la evolución de la vida. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, análisis, discusión y comunicación.\n–\tObservación, análisis y discusión de la biogeografía de los seres vivos en el planeta.\n–\tExperimentación (guiada) con rocas o resinas con fósiles. Procedimiento: descripción, comparación, análisis, discusión y comunicación.\n–\tIndagación sobre las estructuras y funciones de los sistemas y aparatos en animales y en el ser humano. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación (guiada), análisis, discusión y comunicación.\n–\tAnálisis de características de la transmisión del impulso nervioso.\n–\tEnfermedades de los sistemas muscular, óseo y nervioso. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tInvestigación sobre los cambios morfológicos y fisiológicos que ocurren en la pubertad. Procedimiento: formulación de preguntas, búsqueda de información, ejecución y exposición.\n–\tIndagación sobre la situación de las Áreas protegidas de la República Dominicana. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, uso de mapas, planificación y diseño, ejecución, conclusión y exposición.\n \n–\tElaboración de un listado de vacunas contra enfermedades infecciosas. Planteamiento de preguntas, búsqueda de información, lectura y comentarios, planificación y diseño, ejecución, conclusión y exposición.\n–\tEnfermedades infecciosas causadas por bacterias y hongos. Procedimiento: observación, descripción, comparación, verificación de fuentes de información, experimentación, análisis, discusión y comunicación.\n \n ","attitudinal":"–\tUtilización sostenible de los recursos materiales y tecnológicos de que dispone.\n–\tDemostración de interés por conocer sobre las propiedades y características de la materia y la energía, así como por utilizar herramientas y construir máquinas comprendiendo sus mecanismos y funcionamiento."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.193Z');
