INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-401', 'sociales', '4to', '{"id":"soc-401","name":"Geografía Física de la República Dominicana","themes":[{"id":"t-soc-401-1","name":"Relieve, Clima e Hidrografía","subthemes":[{"id":"st-soc-401-1-1","name":"Sistemas montañosos, llanuras y valles principales"},{"id":"st-soc-401-1-2","name":"El clima tropical y sus variaciones en la isla"},{"id":"st-soc-401-1-3","name":"Ríos, lagos y zonas costeras dominicanas"},{"id":"st-soc-401-1-4","name":"División territorial: provincias y municipios"}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-401-block-1","themes":["Relieve, Clima e Hidrografía"],"conceptual":"Geografía del Caribe y las Antillas.\n–\tEl Caribe, Antillas Mayores y Menores: características físicas, sociales y culturales.\n–\tEl Caribe, las Antillas e Isla de Santo Domingo: posición, relieve, clima y población.","procedural":"Ubicación en mapas de las Antillas mayores y menores:\n–\tSelección de fuentes sobre el Caribe y las Antillas (mapas y publicaciones).\n–\tIdentificación de las Antillas mayores en un mapa del Caribe.\n–\tIdentificación de la isla de Santo Domingo en un mapa del Caribe.\n–\tUso de la rosa de los vientos para identificar las Antillas que están al norte, sur, este y oeste.\n–\tUtilización de escala y leyendas en la lectura del mapa del Caribe.\n–\tElaboración de leyendas sencillas con colores que representan las Antillas que están al norte, sur, este y oeste.\n–\tElaboración de infografía sobre las Antillas y la isla de Santo Domingo.\n–\tElaboración de cuadros sencillos sobre la cantidad de Antillas mayores y menores y la población de algunas de ellas.\n–\tElaboración de cuadros sinópticos sobre el clima en las Antillas mayores y menores.\n–\tElaboración de proyectos de investigación sencillos sobre el relieve y el clima de las Antillas.\n–\tIdentificación, con la ayuda del docente, de mapas de población de las Antillas y la República Dominicana.","attitudinal":"–\tValoración del Caribe y las Antillas.\n–\tValoración del uso de fuentes confiables sobre temas históricos y geográficos."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.197Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-402', 'sociales', '4to', '{"id":"soc-402","name":"La Sociedad Taína y Primeros Pobladores","themes":[{"id":"t-soc-402-1","name":"Cultura y Vida Taína","subthemes":[{"id":"st-soc-402-1-1","name":"Origen, migración y asentamiento de los taínos"},{"id":"st-soc-402-1-2","name":"Organización social, política y el rol de los caciques"},{"id":"st-soc-402-1-3","name":"Religión, agricultura, arte y costumbres taínas"},{"id":"st-soc-402-1-4","name":"Presencia taína en la cultura dominicana actual"}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-402-block-1","themes":["Cultura y Vida Taína"],"conceptual":"Educación Ciudadana, patrimonio natural y cultural de la República Dominicana. – Organización de la sociedad\n–\tConceptos de nación, estado y gobierno.\n–\tEstado social, democrático y de derechos.\n–\tTerritorio nacional.\n–\tLos poderes del Estado.\n–\tEstado y Constitución.\n–\tSímbolos patrios.\n ","procedural":"–\tAnálisis de los conceptos de nación, Estado y gobierno y Constitución, planteando su punto de vista.\n–\tElaboración de informes de lectura y monografía sobre la importancia de los Poderes del Estado en el equilibrio democrático.\n–\tLectura y comentario de texto relacionados al himno nacional y sobre el origen de la bandera dominicana y evaluación del contexto en que se crearon.\n ","attitudinal":"–\tRespeto y tolerancia hacia los diferentes grupos humanos que conforman la población de la República Dominicana.\n–\tInterés por conocer sobre el Estado democrático y los poderes del Estado. \n–\tValoración de su vida y la de las demás personas.\n–\tPlantea soluciones a conflictos mediante el diálogo y el consenso.\n–\tValoración del diálogo, la cultura de paz para la prevención y solución de conflictos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.197Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-403', 'sociales', '4to', '{"id":"soc-403","name":"Descubrimiento, Colonización y Esclavitud","themes":[{"id":"t-soc-403-1","name":"El Encuentro de dos Culturas","subthemes":[{"id":"st-soc-403-1-1","name":"Llegada de los españoles en 1492 e impacto del choque cultural"},{"id":"st-soc-403-1-2","name":"Sistemas de explotación: factoría colombina y encomiendas"},{"id":"st-soc-403-1-3","name":"Introducción de la caña de azúcar y la esclavitud africana"},{"id":"st-soc-403-1-4","name":"Rebeliones de esclavos y el cimarronaje en La Española"}]}],"grade_levels":["4to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-403-block-1","themes":["El Encuentro de dos Culturas"],"conceptual":"Educación Ciudadana, patrimonio natural y cultural de la República Dominicana. – Organización de la sociedad\n–\tConceptos de nación, estado y gobierno.\n–\tEstado social, democrático y de derechos.\n–\tTerritorio nacional.\n–\tLos poderes del Estado.\n–\tEstado y Constitución.\n–\tSímbolos patrios.\n ","procedural":"–\tAnálisis de los conceptos de nación, Estado y gobierno y Constitución, planteando su punto de vista.\n–\tElaboración de informes de lectura y monografía sobre la importancia de los Poderes del Estado en el equilibrio democrático.\n–\tLectura y comentario de texto relacionados al himno nacional y sobre el origen de la bandera dominicana y evaluación del contexto en que se crearon.\n ","attitudinal":"–\tRespeto y tolerancia hacia los diferentes grupos humanos que conforman la población de la República Dominicana.\n–\tInterés por conocer sobre el Estado democrático y los poderes del Estado. \n–\tValoración de su vida y la de las demás personas.\n–\tPlantea soluciones a conflictos mediante el diálogo y el consenso.\n–\tValoración del diálogo, la cultura de paz para la prevención y solución de conflictos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.197Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-501', 'sociales', '5to', '{"id":"soc-501","name":"Geografía del Continente Americano","themes":[{"id":"t-soc-501-1","name":"El Espacio Americano","subthemes":[{"id":"st-soc-501-1-1","name":"Límites, relieve, climas e hidrografía de América"},{"id":"st-soc-501-1-2","name":"División regional: Norte, Centro, Suramérica y el Caribe"},{"id":"st-soc-501-1-3","name":"Población, movimientos migratorios y diversidad cultural"}]}],"grade_levels":["5to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-501-block-1","themes":["El Espacio Americano"],"conceptual":"","procedural":"","attitudinal":""}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.197Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-502', 'sociales', '5to', '{"id":"soc-502","name":"La Isla de Santo Domingo en los Siglos XVII y XVIII","themes":[{"id":"t-soc-502-1","name":"El Surgimiento de dos Colonias","subthemes":[{"id":"st-soc-502-1-1","name":"Las devastaciones de Osorio (1605-1606) y sus consecuencias"},{"id":"st-soc-502-1-2","name":"El contrabando y surgimiento de la colonia francesa"},{"id":"st-soc-502-1-3","name":"Santo Domingo Español y Saint-Domingue Francés"},{"id":"st-soc-502-1-4","name":"Los tratados fronterizos (Ryswick, Aranjuez)"}]}],"grade_levels":["5to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-502-block-1","themes":["El Surgimiento de dos Colonias"],"conceptual":"","procedural":"","attitudinal":""}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.198Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-503', 'sociales', '5to', '{"id":"soc-503","name":"Independencia Nacional y Nacimiento de la República","themes":[{"id":"t-soc-503-1","name":"La Lucha por la Soberanía","subthemes":[{"id":"st-soc-503-1-1","name":"La ocupación haitiana (1822-1844) y causas del descontento"},{"id":"st-soc-503-1-2","name":"Fundación de la sociedad secreta La Trinitaria y Juan Pablo Duarte"},{"id":"st-soc-503-1-3","name":"El 27 de febrero de 1844 y las batallas por la independencia"},{"id":"st-soc-503-1-4","name":"La anexión a España en 1861 y la Guerra Restauradora"}]}],"grade_levels":["5to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-503-block-1","themes":["La Lucha por la Soberanía"],"conceptual":"","procedural":"","attitudinal":""}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.198Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-601', 'sociales', '6to', '{"id":"soc-601","name":"Geografía Mundial y Relaciones del Caribe","themes":[{"id":"t-soc-601-1","name":"El Espacio Geográfico Mundial","subthemes":[{"id":"st-soc-601-1-1","name":"Líneas imaginarias terrestres: paralelos y meridianos"},{"id":"st-soc-601-1-2","name":"Continentes y océanos: características físicas y políticas"},{"id":"st-soc-601-1-3","name":"El Caribe insular y continental: relieve y recursos"},{"id":"st-soc-601-1-4","name":"Sostenibilidad y preservación de recursos naturales mundiales"}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-601-block-1","themes":["El Espacio Geográfico Mundial"],"conceptual":"\"Geografía Humana\"\nGeografía como ciencia y sus ramas.\n–\tEl espacio geográfico.\n–\tAspectos geográficos de los continentes: Ubicación, límites, superficie, relieve, clima, hidrografía, economía, población, cultura.","procedural":"Identificación y uso de fuentes confiables de la geografía como ciencia y sus ramas.\n–\tAnálisis de conceptos de geografía, ubicación, relieve, ubicación, cultura civilización.\n–\tSelección de fuentes confiables sobre la geografía como ciencia.\n–\tAnálisis de los conceptos básicos de geografía y su objeto de estudio.\n–\tComparación de las ramas de la geografía física y humana.\n–\tElaboración de cuadros sinópticos de los aspectos geográficos de los continentes: relieve, clima, hidrografía, economía, población, cultura.\n–\tAnálisis de mapas sobre la población de los continentes.\nIdentifica en mapamundi, países en donde se ubicaban las civilizaciones antiguas.\n–\tUtilización de lecturas de fuentes seguras y confiables sobre la geografía humana y los continentes, siguiendo procedimientos de análisis.\n–\tPresentación de un resumen sobre los aspectos estudiados de la geografía humana y los aspectos geográficos de los continentes.","attitudinal":"–\tInterés por el uso de fuentes confiables de investigación de geografía, historia y ciudadanía.\n–\tValoración de la geografía en el estudio del espacio natural."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.198Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-602', 'sociales', '6to', '{"id":"soc-602","name":"La República Dominicana en el Siglo XX y Contemporáneo","themes":[{"id":"t-soc-602-1","name":"Dictadura, Democracia y Revolución","subthemes":[{"id":"st-soc-602-1-1","name":"La primera intervención militar norteamericana (1916-1924)"},{"id":"st-soc-602-1-2","name":"La dictadura de Rafael Leónidas Trujillo (1930-1961)"},{"id":"st-soc-602-1-3","name":"La revolución de abril de 1965 y la intervención militar de la OEA"},{"id":"st-soc-602-1-4","name":"El retorno a la democracia y el proceso electoral contemporáneo"}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-602-block-1","themes":["Dictadura, Democracia y Revolución"],"conceptual":"América en el siglo XX: Estados Unidos, Canadá y \nLatinoamérica\n– Imperios coloniales y su impacto en América durante los siglos XX.\n ","procedural":"–\tAnálisis de la incidencia de los imperios coloniales impacto en América durante los siglos XIX y XX.\n–\tComprensión del papel de los imperios coloniales en América en el siglo XX.\n–\tInterés por comprender la situación política de América en la primera mitad del siglo XIX. \n–\tIdentificación de fuentes confiables y seguras sobre la historia de América.\n ","attitudinal":"–\tInterés por la situación política de América en el siglo XX.\n–\tValoración de los sectores que resistieron las intervenciones de los Estados Unidos de América."}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.198Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('soc-603', 'sociales', '6to', '{"id":"soc-603","name":"Constitución Dominicana y Ciudadanía Responsable","themes":[{"id":"t-soc-603-1","name":"Derechos Ciudadanos y Estructura del Estado","subthemes":[{"id":"st-soc-603-1-1","name":"La Constitución Dominicana y los derechos fundamentales"},{"id":"st-soc-603-1-2","name":"Los tres poderes del Estado: Ejecutivo, Legislativo y Judicial"},{"id":"st-soc-603-1-3","name":"Deberes ciudadanos e importancia del voto popular"},{"id":"st-soc-603-1-4","name":"Cultura de paz, derechos de los niños y resolución pacífica"}]}],"grade_levels":["6to"],"subjectId":"sociales","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"soc-603-block-1","themes":["Derechos Ciudadanos y Estructura del Estado"],"conceptual":"Leónidas Trujillo Molina y la vulneración de los derechos humanos estatales durante los años 1930-1961. \n–\tRevolución de Abril (Caamaño y los constitucionalistas y el grupo de San Isidro).","procedural":"–\tAnálisis de periodos de la historia dominicana, mediante comparaciones críticas 1916 y 1965.\n–\tComprensión de los principales acontecimientos históricos de América en el siglo XX.\n–\tAnálisis del impacto de los imperios coloniales en América.\n–\tAnálisis del merengue de Nico Lora “vienen los americanos” u otras canciones que se refieran al hecho histórico: Imágenes, caricaturas, poemas.\n–\t-Realización de comic, dibujos, pancartas, frases, u otras expresiones donde expresen sus opiniones sobre la ocupación por parte de Estados Unidos.\n–\tElaboración de líneas de tiempo de los acontecimientos históricos de 1960- 1965.\n–\tElaboración de líneas de tiempo sobre acontecimientos de 1916-1924. Formulación de hipótesis sobre los antecedentes de la Dictadura de Trujillo.\n–\tPlanteamiento de la hipótesis.\n–\tComprobación de la hipótesis.\n–\tCorrección de la hipótesis.\n–\tAnálisis del impacto social, político, económico y religioso de la Era de Trujillo.\n–\tLevantamiento de informaciones en museos y archivos sobre los movimientos opositores al régimen de Trujillo.\n–\tLevantamiento de informaciones sobre los acontecimientos que propiciaron la Dictadura de \nTrujillo.\n–\tAnálisis de documentales y videos: para determinar las características económicas, políticas y socioculturales de la de Dictadura Trujillo.\n–\tIdentificación de los factores que propiciaron la caída de Trujillo.\n–\tAnálisis de documentos y videos sobre los acontecimientos ocurridos de 1961 al 1966.\n–\tExplicación de las causas y consecuencias del Golpe de Estado a Juan Bosch.\n–\tElaboración de periódicos escolares sobre los sectores enfrentados en la Guerra de Abril.\n–\tAnálisis crítico del gobierno de García Godoy en 1966.\n–\tInvestigación en fuentes de investigación confiables sobre los doce años de Joaquín Balaguer.\n–\tIdentificación de las características principales que propiciaron su ascenso al poder.\n–\tAnálisis del impacto de los 12 años en la sociedad dominicana.\n–\tElaboración de monografías sobre los periodos históricos de 1978-1986; 1986-1994.\n–\tRealización de un informe de lectura sobre el papel de la sociedad civil de 1990 a la actualidad.\n–\tElaboración de textos argumentativos sobre la crisis electoral de 1990 y 1994.\n–\tRealización análisis comparativos sobre los aspectos sociales, políticos y económicos de los gobiernos del PRD, PRSC y los del PLD hasta el 2020.\n–\tPresentación de un resumen final sobre los procesos históricos estudiados de 1960 a la actualidad.\n \n ","attitudinal":"–\tPreocupación por comprender los periodos históricos de la República Dominicana de 1916-1924;1924-1930. \n–\tInterés por comprender los acontecimientos históricos principales en la Era de Trujillo.\n–\tReflexión crítica sobre el Golpe de Estado a Juan Bosch y la Guerra de Abril.\n–\tActitud crítica ante el papel de los constitucionalistas y el sector de San Isidro.\n–\tInterés por los acontecimientos históricos que propiciaron el gobierno de Héctor García Godoy.\n–\tAnálisis crítico de los 12 de Años de Joaquín Balaguer.\n–\tReflexión crítica sobre los gobiernos de 1978-1986: 1986-2000.\n–\tInterés por comprender los acontecimientos históricos de 2000 al 2020.\n– Interés por comprender la incidencia de los partidos políticos y la sociedad civil en la solución de problemas. \n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.199Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('fh-401', 'formacion-humana', '4to', '{"id":"fh-401","name":"Los Valores Humanos y la Convivencia Familiar","themes":[{"id":"t-fh-401-1","name":"Convivencia Familiar y Autoestima","subthemes":[{"id":"st-fh-401-1-1","name":"El amor, el respeto, la solidaridad y la tolerancia en el hogar"},{"id":"st-fh-401-1-2","name":"Derechos y responsabilidades de los niños en su núcleo familiar"},{"id":"st-fh-401-1-3","name":"Autoestima y el aprecio por las características personales"}]}],"grade_levels":["4to"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"fh-401-block-1","themes":["Convivencia Familiar y Autoestima"],"conceptual":"-\tEl cuerpo\n-\tCambios del cuerpo\n-\tCuidado y protección del cuerpo - Criatura de Dios.\n-\tImportancia y necesidad del trabajo.\n-\tEl trabajo mejora la creación de Dios.\n-\tTrabajo científico y tecnológico.\n-\tDesarrollo del trabajo humano.\n-\tTrabajo tecnológico y creación de Dios.\n-\tCrecimiento físico, afectivo-sexual y espiritual.\n-\tLa naturaleza, creación de Dios.\n-\tCuidado y respeto por la naturaleza.\n-\tEl amor de Dios expresado en Jesús de Nazaret\n ","procedural":"-\tSocialización de las características y cambios que se generan en el cuerpo de niños y niñas mediante la utilización de recursos diversos.\n-\tDramatización sobre diferentes formas en que se puede cuidar y proteger el cuerpo de niños y niñas.\n-\tIdentificación de citas bíblicas donde se resalta el respeto al cuerpo como creación de Dios.\n-\tPresentación artística donde muestre que su cuerpo es creación de Dios.\n-\tRepresentación en que se destaca el cuerpo como expresión hacia Dios y del amor de Dios hacia las personas.\n-\tRealización de entrevistas sobre el cuidado del cuerpo a padres, profesores y otros profesionales.\n-\tInvestigación de acciones de respeto e irrespeto a su cuerpo.\n-\tSocialización sobre la importancia del cuerpo y todas sus partes como regalo de Dios a partir 1Corintios 12, 12- 26 y otros textos.\n-\tIdentificación en láminas y otros recursos de las maravillas del cuerpo. \n-\tElaboración de pautas sobre cuidado y protección del cuerpo en los diferentes contextos.\n-\tOrganización de celebración de agradecimiento a Dios por el cuerpo, su cuidado y protección a partir de diferentes expresiones artísticas.\n- Presentación donde se muestre que somos criaturas de Dios a partir de citas bíblicas y otras fuentes.\n \n-\tSocialización sobre el trabajo que realizan el padre, la madre y familiares para sustentar a sus familias y su aporte para el desarrollo de la sociedad. \n-\tConstatación del desarrollo de la sociedad por el trabajo realizado a través de los aportes de la ciencia y la tecnología.\n-\tArgumentación de la necesidad del trabajo en la vida de las personas.\n-\tComparación entre trabajos que promueven al ser humano y su dignidad y otros que no lo promueven. \n-\tExploración sobre la obligación y la necesidad del trabajo para la vida en sociedad.\n-\tAnálisis del Salmo 8 y su referencia al ser humano con relación a todo lo creado.\n-\tOrganización y celebración de acción de gracias por los trabajos que realizan las personas en los diferentes ambientes, utilizando el Salmo 8 y las producciones realizadas.\n-\tInvestigación de los beneficios que el ser humano ha logrado a través de su trabajo científico y tecnológico. \n-\tIndagación sobre las características, ventajas y desventajas de los juegos electrónicos y del uso de la tecnología.\n-\tInvestigación sobre instituciones y/o personas que trabajan para mejorar lo que Dios ha creado (medicina, arquitectura, desarrollo de las TIC, las ciencias, las artes, entre otras).\n \n-\tRepresentación de actividades que muestren la responsabilidad y participación de las personas en el cuidado de la creación a través de la ciencia y la tecnología.\n-\tExpresiones diversas de agradecimiento a Dios por los aportes de las ciencias y las tecnologías a su obra creada utilizando diferentes recursos. \n-\tOrganización de campañas escolares sobre el cuidado y la protección de las personas y del medio natural creado por Dios haciendo uso de herramientas tecnológicas.\n ","attitudinal":"-\tRespeto hacia los demás y sus diferencias \n-\tGratitud a Dios por haberlo creado. \n-\tAdmiración por su cuerpo.\n-\tValoración de su cuerpo.\n \n-\tRespeto por el trabajo de las personas adultas.\n-\tAprecio por los beneficios del trabajo.\n-\tResponsabilidad en las tareas propias del hogar y la escuela.\n-\tAgradecimiento a Dios por permitir a las personas colaborar con su creación a través de la ciencia y la tecnología.\n-\tAdmiración por los avances científicos y tecnológicos.\n-\tAprecio por los aportes de la ciencia y la tecnología en el desarrollo de la sociedad.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.200Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('fh-501', 'formacion-humana', '5to', '{"id":"fh-501","name":"Convivencia Pacífica, Amistad y Empatía","themes":[{"id":"t-fh-501-1","name":"El Diálogo y las Relaciones Interpersonales","subthemes":[{"id":"st-fh-501-1-1","name":"La amistad sincera, el compañerismo y la lealtad escolar"},{"id":"st-fh-501-1-2","name":"Estrategias de resolución pacífica de conflictos en el aula"},{"id":"st-fh-501-1-3","name":"El respeto por la diversidad social e inclusión escolar"}]}],"grade_levels":["5to"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"fh-501-block-1","themes":["El Diálogo y las Relaciones Interpersonales"],"conceptual":"-\tLa maravilla del cuerpo. \n-\tCambios y desarrollo del cuerpoCuidado y respeto por el cuerpo. Importancia del cuerpo.\n-\tDesarrollo afectivo sexual - Deberes y derechos de la niñez.\n-\tNormas de convivencia.\n-\tConflictos interpersonales. \n-\tRelaciones interpersonales en la familia y escuela.\n-\tFamilia y crecimiento integral.\n-\tTipos de familia.\n-\tDerechos y deberes en la familia.\n-\tRoles en la familia.\n-\tCorresponsabilidad y diálogo en la familia.\n-\tFamilia, regalo de Dios.\n ","procedural":"-\tElaboración de un cuadro comparativo sobre los cambios ocurridos desde su nacimiento en los aspectos físico, emocional y social.\n-\tIdentificación y exposición de situaciones de la vida cotidiana que permiten el desarrollo físico, espiritual y emocional de los niños, niñas y adolescentes.\n-\tInteracción acerca de su desarrollo afectivo sexual.\n-\tAnálisis de noticias, sucesos y situaciones que dañan o maltratan y violentan el cuerpo. \n-\tFormulación y aplicación de medidas para el respeto y cuidado del cuerpo a partir del texto bíblico de 1 Corintios 6, 19- 20.\n-\tElaboración de distintas técnicas y recursos (murales, exposiciones, conversaciones, redacciones…) en los que se destaquen las acciones realizadas con el cuerpo que ayudan a la comunicación con las personas. \n-\tOrganización de una celebración donde se exponga todo lo maravilloso que puede hacer con su cuerpo y agradezca a Dios por el regalo del cuerpo y sus capacidades.\n \n-\tSocialización de las normas y leyes que se practican en la convivencia cotidiana, en la familia, la escuela y la comunidad. \n-\tInvestigación sobre las principales normas de convivencia para una relación armónica con las demás personas.\n-\tOrganización de una mesa redonda donde se construya en equipo las normas para mejorar el comportamiento en el aula.\n-\tExposición de los aspectos que hay que fomentar para una convivencia armónica en las relaciones con las demás personas.\n-\tRealización de actividades (sociodramas, exposiciones, conversatorios) donde se presenten situaciones conflictivas en las relaciones interpersonales y la forma de resolverlas.\n-\tExploración sobre la convivencia familiar, destacando los roles y la corresponsabilidad en la familia. \n-\tConstrucción de la historia familiar consultando padres, hermanos, abuelos, bisabuelos tíos, y otras personas de su familia. \n-\tComposición sobre la familia como espacio de crecimiento físico, moral y espiritual.\n-\tInvestigación sobre los derechos y deberes que les corresponden a la familia.\n-\tAnálisis de roles y relaciones entre padres, madres, tutores, hijos e hijas a partir del texto de Efesios 6,1-4\n-\tInvestigación sobre las características de los diferentes tipos de familia en la sociedad dominicana.\n-\tOrganización de una celebración en la que se exponen las producciones, se destaque el amor, el cuidado, la colaboración entre familiares y agradecimiento a Dios por el regalo de su familia.\n-\tInvestigación sobre las características de los diferentes tipos de familia en la sociedad dominicana.\n-\tOrganización de una celebración en la que se exponen las producciones, se destaque el amor, el cuidado, la colaboración entre familiares y agradecimiento a Dios por el regalo de su familia.\n \n-\tArgumentación sobre cómo el trabajo de las personas adultas y la tecnología contribuyen al desarrollo humano y espiritual de los niños, niñas y adolescentes.\n-\tAnálisis sobre la obligatoriedad del trabajo según el texto bíblico de 2 Tesalonicenses 3,10-13.\n-\tInvestigación de los diferentes aportes y beneficios del trabajo de las personas adultas y la tecnología al desarrollo de la obra creadora de Dios.\n-\tSocialización acerca de la necesidad de las ciencias y las tecnologías para el desarrollo social, cultural y espiritual de las personas.\n-\tDramatización de situaciones reales sobre el uso adecuado e inadecuado de las tecnologías en la familia, la escuela y la sociedad.\n-\tRealización de entrevistas a familiares, maestros y vecinos acerca de la importancia de la inclusión de principios éticos en la realización de los trabajos escolares.\n-\tElaboración de murales informativos sobre la importancia del implementar valores éticos en el uso y manejo de las ciencias y las tecnologías en actividades personales, familiares y escolares.\n-\tCelebración festiva donde se expongan las producciones, se reconozcan los beneficios del trabajo de las personas adultas y de las tecnologías en el desarrollo humano y espiritual de los niños, y niñas y adolescentes.\n- Realización de una mesa redonda donde se plantee los principales problemas medio ambientales, identificando sus causas, consecuencias y planteando medidas de soluciones para mejorar nuestra casa común.\n \n-\tInvestigación sobre las principales normas, leyes ecológicas y \nmandamientos ambientales que existen para la protección y cuidado del entorno natural.\n-\tRealización de una campaña de implementación de acciones en nuestra vida cotidiana que contribuyan al cuidado y protección del entorno natural.\n-\tElaboración de un proyecto donde se implementen acciones y cuidado del entorno natural como nuestra casa común, en su contexto familiar, comunitario, escolar y social. \n-\tOrganización de una “creatividad ecológica”, donde los estudiantes elaboren dibujos, fotos, poesías, composiciones, afiches en torno a las soluciones ecológicas y medio ambientales. \n-\tSocialización sobre el sentido de la Navidad y los sentimientos que produce esta celebración en la familia, la escuela, la comunidad y el país.\n-\tPresentación y contemplación del nacimiento de Jesús donde se agradezca a Dios por el nacimiento de su Hijo y por tenerlo como ejemplo de vida.\n-\tPresentación de los siguientes aspectos sobre Palestina: Características geográficas, gastronomía, producción agrícola, costumbres religiosas, forma de gobiernos, lugares turísticos. \n-\tIdentificación y presentación de costumbres religiosas en su familia y comunidad a partir del texto bíblico de Lucas 2, 21-24 y 41-42.\n-\tComparación ente las costumbres y prácticas religiosas de su familia y comunidad a con las del país de Jesús de Nazaret. \n-\tExposición sobre los valores que Jesús predicó y practico al relacionarse con las personas de su tiempo. \n \n-\tRealización de síntesis del mensaje de Jesús sobre el amor y el perdón apoyándose en los textos de Juan 13,3436 y Mateo 18,21-22.\n-\tOrganización de un teatro bíblico sobre la pasión, muerte y resurrección de Jesús a partir de los textos de Lucas 24, 1- 12; 24, 13- 35; Marcos 16, 1- 8 y Juan 20, 1- 19 y otros recursos audiovisuales. \n-\tOrganización de una celebración donde los estudiantes presenten gestos que expresen amor y perdón entre ellos. \n \n ","attitudinal":"-\tAdmiración ante lo que puede hacer con su cuerpo. \n-\tAceptación y alegría de los cambios experimentados en su cuerpo y su persona. \n-\tRechazo al maltrato de su cuerpo y el de otras personas. \n-\tDenuncia de todo tipo de acoso o abuso sexual. \n-\tReclamación de  los derechos de la niñez y cumple con sus deberes.\n-\tPráctica del diálogo y la negociación como forma de solucionar los conflictos interpersonales.\n-\tAprecio por la actitud de amar y perdonar a los demás.\n-\tDisposición para dar y recibir amor y perdón.\n-\tCuriosidad por conocer su ascendencia familiar.\n-\tComunicación y colaboración en su familia.\n-\tAgradecimiento a Dios por el regalo de su familia.\n \n-\tGratitud a Dios por lo que las personas pueden hacer con su trabajo para mejorar la sociedad.\n-\tReconocimiento del esfuerzo y sacrificio de las personas que trabajan. \n-\tAdmiración por los beneficios que el trabajo digno trae a la persona, a la sociedad y al entorno natural.\n-\tAgradecimiento a Dios por las capacidades personales en el manejo y buen uso de las ciencias y las tecnologías.\n-\tRespeto de los principios y valores éticos en el uso de las tecnologías.\n-\tGratitud a Dios por lo que las personas pueden hacer con su trabajo para mejorar la sociedad.\n-\tReconocimiento del esfuerzo y sacrificio de las personas que trabajan. \n-\tAdmiración por los beneficios que el trabajo digno trae a la persona, a la sociedad y al entorno natural.\n-\tAgradecimiento a Dios por las capacidades personales en el manejo y buen uso de las ciencias y las tecnologías.\n-\tRespeto de los principios y valores éticos en el uso de las tecnologías.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.201Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('fh-601', 'formacion-humana', '6to', '{"id":"fh-601","name":"Dignidad Humana, Derechos de la Niñez y Ecología","themes":[{"id":"t-fh-601-1","name":"Valores Sociales y Ecología Espiritual","subthemes":[{"id":"st-fh-601-1-1","name":"El valor sagrado de la vida humana y la dignidad personal"},{"id":"st-fh-601-1-2","name":"Derechos y deberes de la niñez y la erradicación del maltrato"},{"id":"st-fh-601-1-3","name":"Compromiso social y ecológico: cuidado de la \"casa común\""}]}],"grade_levels":["6to"],"subjectId":"formacion-humana","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"fh-601-block-1","themes":["Valores Sociales y Ecología Espiritual"],"conceptual":"-\tEl valor del cuerpo humano.\n-\tHombre y mujer complementarios: semejanzas y diferencias.\n-\tCaracterísticas del niño y de la niña.\n-\tSituaciones de riesgo en la niñez, maltrato y abuso infantil.\n-\tDeberes y derechos de la niñez. \n-\tBuen trato hacia las personas - Inclusión y discriminación.\n-\tBienestar propio y el de los demás.\n-\tValor del trabajo humano.\n-\tEl trabajo infantil: Necesidades, riesgos y consecuencias. \n-\tCiencia, tecnología y vida.\n-\tAportes de la ciencia y la tecnología\n-\tExpresiones del amor de Dios.\n-\tDesarrollo físico, cognitivo, afectivo, sexual y espiritual del adolescente.\n-\tLa familia como lugar de afecto y cariño.\n-\tRelaciones del adolescente con la familia, la escuela y el entorno.\n-\tCuidado y protección del entorno natural.\n-\tBúsqueda de soluciones a situaciones que afectan el entorno natural.\n-\tJesús nace y crece en sabiduría y gracia.\n-\tEstilo de vida de Jesús.\n-\tJesús ante el sufrimiento y muerte en la cruz.\n-\tLa resurrección, triunfo de Jesús.\n ","procedural":"-\tInvestigación acerca de la igualdad del hombre y la mujer según la Declaración Universal de los Derechos Humanos.\n-\tArgumentación y representación sobre los derechos fundamentales establecidos en la Ley 136- 03 que establece el Código para el Sistema de Protección y los \nDerechos Fundamentales de Niños, Niñas y Adolescentes República Dominicana.\n-\tOrganización de una celebración en que se agradezca a Dios por los aprendizajes adquiridos con relación al valor de su cuerpo, los derechos fundamentales de la niñez y la adolescencia, sus deberes y el buen trato a los demás.\n-\tDebate sobre el trabajo infantil apoyado en los artículos 34, 37, 40 del Código para la Protección de los Derechos de los Niños. ","attitudinal":"-\tReconocimiento de sus deberes y exigencia de sus derechos.\n-\tAgradecimiento a Dios por la existencia de leyes, personas e instituciones que protegen a la niñez. "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.201Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('ef-401', 'educacion-fisica', '4to', '{"id":"ef-401","name":"Esquema Corporal, Lateralidad y Coordinación","themes":[{"id":"t-ef-401-1","name":"Coordinación y Expresión Motriz","subthemes":[{"id":"st-ef-401-1-1","name":"Equilibrio estático y dinámico en diferentes superficies"},{"id":"st-ef-401-1-2","name":"Lateralidad y orientación espacio-temporal en desplazamientos"},{"id":"st-ef-401-1-3","name":"Juegos tradicionales y dinámicas de recreación grupal"}]}],"grade_levels":["4to"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"ef-401-block-1","themes":["Coordinación y Expresión Motriz"],"conceptual":"El cuerpo como medio de expresión y comunicación: gesto, movimiento, mímica, expresión corporal. Ritmo y movimiento (pulso, acento, compás).\nHabilidades motrices básicas: \n-\tLocomotoras (caminar, rodar, reptar, correr, saltar -horizontal, vertical y en profundidad- marchar, “saltar”, trepar). \n-\tManipulativas (lanzar, atrapar, picar, rodar, halar, empujar, mover y golpear objetos con ayuda de otros implementos, golpear, patear, atrapar, controlar objetos con diferentes partes del cuerpo). De control corporal (girar, flexionar, balancear).\nCapacidades físicas:\n-\tCoordinativas (equilibrio, acoplamiento, orientación, diferenciación, reacción, adaptación, ritmo).\n-\tCondicionales (velocidad -gestual, de reacción, de desplazamiento-, flexibilidad, resistencia aeróbica).\n-Gimnasia general.\n-\tJuegos cooperativos y de oposición.\n-\tJuegos tradicionales y populares.\n-\tAjedrez (el tablero, las piezas).\n ","procedural":"-\tCreación y realización de series de movimientos utilizando diversos implementos: aros, cuerdas, bastones, pañuelos, globos, pelotas, entre otros.\n-\tRealización de combinaciones de movimientos (saltos, equilibrios y giros).\n-\tEjecución de carreras con y sin obstáculos, con y sin control del tiempo, en forma individual y en grupo.\n-\tExperimentación de diferentes formas de saltar en forma vertical y horizontal, con y sin desplazamiento, aplicando técnicas básicas.\n-\tRealización de diversas formas de lanzamientos utilizando diferentes implementos, aplicando técnicas y reglas sencillas.\n-\tRealización, creación y reproducción de juegos de persecución, colaboración, relevos, saltos y lanzamientos, tradicionales y no tradicionales.\n-\tExperimentación a través del juego de diversas posibilidades de movimiento y expresión.\n-\tEjercicios de organización y control. Formaciones en filas, hileras, columnas, círculos, entre otras.\n-\tEjecución de juegos de conducción de implementos.\n \n-\tUtilización de secuencias rítmicas relacionándolas con movimientos corporales, utilizando herramientas y/o recursos físicos y audiovisuales.\n-\tEjecución de rodadas corporales en diferentes planos y direcciones.\n-\tEjecución de posiciones elementales de relajación corporal, después de la actividad física.\n-\tPráctica de hábitos de higiene y normas de comportamiento durante la realización de las actividades físicas.\n-\tRealización de juegos de correr utilizando las técnicas básicas en la carrera de relevos (carrera, pase y recepción del testigo y llegada).\n-\tRealización de juegos para el reconocimiento de las casillas, filas, columnas y diagonales del tablero de ajedrez, en medio físico, digital o virtual.\n-\tRealización de juegos para el aprendizaje del nombre, disposición en el tablero y movimiento de las piezas.\n-\tExploración de diferentes posturas y toma de conciencia de las correctas, en diferentes acciones como: \nlevantar objetos, desplazamientos, subir y bajar escaleras, entre otros.\n ","attitudinal":"-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividad física, sin discriminación por género, origen, edad u otra condición.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su desarrollo, bienestar y conservación de la salud.\n-\tValoración de los juegos tradicionales y populares como parte de su identidad.\n-\tCuidado y protección de los ambientes físicos y naturales en donde practica la actividad física.\n-\tMotivación por el respecto a las normas y reglas establecidas y del juego limpio.\n-\tDisfrute de la relación y comunicación corporal con los y las demás.\n-\tCuidado y protección de su integridad física y la de sus compañeros y compañeras durante la práctica de actividades físicas.\n \n-\tValoración del orden y la limpieza de los espacios en donde se practica la actividad física.\n-\tValoración y respeto por las destrezas y habilidades de cada compañero y compañera al realizar las diversas actividades físicas.\n-\tUtilización de un lenguaje respetuoso y asertivo durante la práctica de las actividades físicas.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.202Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('ef-501', 'educacion-fisica', '5to', '{"id":"ef-501","name":"Atletismo y Aptitud Física Escolar","themes":[{"id":"t-ef-501-1","name":"Iniciación Atlética y Ajedrez","subthemes":[{"id":"st-ef-501-1-1","name":"Carreras de velocidad, resistencia y relevo escolar"},{"id":"st-ef-501-1-2","name":"Técnicas de salto largo y lanzamientos básicos"},{"id":"st-ef-501-1-3","name":"Fundamentos de ajedrez escolar y gimnasia básica"}]}],"grade_levels":["5to"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"ef-501-block-1","themes":["Iniciación Atlética y Ajedrez"],"conceptual":"-\tHabilidades motrices básicas: Locomotoras (caminar, rodar, reptar, correr, saltar, marchar, “salticar”, trepar).\n-\tManipulativas (lanzar, atrapar, picar, rodar, halar, empujar, golpear, patear, atrapar, controlar objetos con diferentes partes del cuerpo).\n-\tDe control corporal (girar, flexionar, balancear).\n-\tCapacidades físicas: Coordinativas \n(equilibrio, coordinación, \norientación, diferenciación, reacción, adaptación, ritmo).\n-\tCondicionales (fuerza explosiva, velocidad, flexibilidad, resistencia aeróbica).\n-\tGimnasia general. Composiciones gimnasticas. Elementos básicos de gimnasia artística, rítmica y acrobática.\n-\tJuegos cooperativos y de oposición.\n-\tJuegos predeportivos.\n-\tAtletismo (reglas básicas, conceptos básicos, saltos y lanzamientos).\n-\tBaloncesto (dribbles, pases, tiros y defensa, clasificación, importancia, reglamento para su ejecución).\n-\tAjedrez (el jaque, el jaque mate, la coronación del peón, el enroque, peón al paso, valor absoluto de las piezas).\n ","procedural":"-\tRealización de elementos de elevación, equilibrio, fuerza y mantenimiento.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en la resolución de situaciones motrices cotidianas, deportivas y recreativas.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en el manejo y utilización de diversos implementos gimnásticos, recreativos y deportivos.\n-\tRealización de ejercicios de relajación corporal, después de la actividad física.\n-\tRealización de juegos utilizando las técnicas básicas de saltar en distancia y altura.\n-\tRealización de juegos en donde se apliquen las técnicas básicas de lanzamiento, con pelotas de diferentes pesos y tamaños.\n-\tRealización de juegos recreativos o predeportivos de baloncesto, donde se apliquen las técnicas de los pases, dribbling y tiro, evadiendo la oposición a través de la cooperación del compañero o la compañera.\n \n-\tRealización de juegos con mates elementales (torre y rey contra rey, dama y rey contra rey)\n-\tRealización de juegos con coronación de peones en diferentes situaciones.\n-\tParticipación en actividades físicas y juegos recreativos en los que se realicen saltos y lanzamientos de objetos con pesos moderados.\n-\tRealiza carreras continuas a ritmo moderado, juegos predeportivos y adaptados en los que se pone de manifiesto su resistencia aeróbica.\n-\tParticipación en juegos adaptados partiendo de situaciones de aprendizaje que promuevan el pensamiento táctico.\n-\tParticipación en juegos predeportivos relacionados con el dribble, pases, tiros y aspectos generales de la defensa.\n-\tDescripción y elaboración de las utilerías e implementos manipulados en baloncesto, atletismo, gimnasia, ajedrez y su utilización, con apoyo de recursos tecnológicos.\n-\tValoración de hábitos de higiene, aseo personal y alimentación saludable en la práctica diaria de actividades físicas.\n ","attitudinal":"-\tExperimentación de diferentes sensaciones, descubrimiento, percepción y mejor entendimiento de sus movimientos y los de los y las demás.\n-\tPráctica del juego limpio, respetando las reglas de los juegos que realiza.\n-\tValoración y práctica de hábitos de higiene y normas de comportamiento.\n-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar realizar actividades físicas.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su desarrollo, bienestar y conservación de la salud.\n-\tCuidado y protección de los ambientes físicos y naturales en donde practica actividades físicas.\n-\tRespeto por la creación de los y las demás.\n-\tValoración del movimiento corporal del compañero y la compañera.\n-\tActitud de aceptación de sí mismo, sí misma y de los y las demás sin discriminación de sexo o nivel de habilidades.\n-\tDemostración de disfrute al participar en las diferentes actividades deportivas y recreativas.\n-\tActitud de cooperación con sus compañeros y compañeras, y de respeto por las reglas y por el/la adversario/a.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.202Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('ef-601', 'educacion-fisica', '6to', '{"id":"ef-601","name":"Juegos Cooperativos y Deportes de Conjunto","themes":[{"id":"t-ef-601-1","name":"Deportes Escolares y Trabajo en Equipo","subthemes":[{"id":"st-ef-601-1-1","name":"Fundamentos técnicos básicos de Baloncesto y Voleibol escolar"},{"id":"st-ef-601-1-2","name":"Fundamentos básicos del Béisbol y fútbol sala"},{"id":"st-ef-601-1-3","name":"Trabajo en equipo, respeto al rival y reglas de juego limpio"}]}],"grade_levels":["6to"],"subjectId":"educacion-fisica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"ef-601-block-1","themes":["Deportes Escolares y Trabajo en Equipo"],"conceptual":"\"Habilidades motrices básicas:\"\n-\tLocomotoras (caminar, rodar, reptar, correr, saltar, marchar, “saltar”, trepar).\n-\tManipulativas (lanzar, picar, rodar, halar, empujar, golpear, patear, atrapar, controlar objetos con diferentes partes del cuerpo). De control corporal (girar, flexionar, balancear).\n \n\"Capacidades físicas:\"\n-\tCoordinativas (equilibrio, coordinación, orientación, diferenciación, reacción, adaptación, ritmo). Condicionales (fuerza explosiva, velocidad de reacción, flexibilidad, resistencia aeróbica).\n \nJuegos predeportivos, \n- \"juegos adaptados.\"\nVoleibol (voleo, golpe bajo, saque, ataque).\nFútbol (conducción del balón, pase, tiro). Béisbol (fildeo, bateo, corrido de bases, características, importancia, reglamento para su ejecución).\nAjedrez (normas generales de la apertura, anotación algebraica).\n ","procedural":"-\tParticipación de los niños y las niñas en las distintas actividades físicas con equidad e igualdad de género.\n-\tDistribución consciente del movimiento en el espacio.\n-\tCombinación de movimientos, formas, formaciones, direcciones y trayectorias de forma creativa.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en la resolución de situaciones motrices cotidianas, deportivas y recreativas.\n-\tAplicación de las habilidades motrices básicas y capacidades físicas en el manejo y utilización de diversos implementos y aparatos gimnásticos, recreativos y deportivos.\n-\tElaboración y descripción de las utilerías e implementos manipulados en fútbol, voleibol, béisbol y ajedrez y su utilización, con apoyo de recursos del medio.\n-\tRealización de juegos de coordinación viso-motora.\n-\tRealización de actividades y juegos recreativos, en los que se efectúen saltos y lanzamientos de objetos con peso moderado.\n-\tRealización de carreras continuas a ritmo moderado.\n \n-\tParticipación en juegos recreativos y deportivos adaptados, en los que se ponga de manifiesto su resistencia aeróbica.\n-\tEjercicios de organización y control. Formaciones en filas, hileras, columnas, círculos, entre otras.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para la conducción del balón.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para los pases y tiros con las extremidades inferiores y la cabeza.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para el bateo.\n-\tEjecución de juegos en los que se apliquen técnicas básicas para atrapadas de aire y de ¨rolling¨.\n-\tEjecución de pequeños juegos de voleibol de cooperación y oposición en los que se apliquen técnicas básicas para el saque, golpe bajo, voleo y ataque.\n-\tParticipación en juegos predeportivos en los que se fildean diferentes móviles y pelotas tanto de rolling como de aire.\n-\tGolpeo de diferentes tipos de pelotas y otros implementos con manos, pies, bates y materiales adaptados para tal uso.\n-\tPráctica de correr entre puntos o bases.\n-\tRealización de ejercicios de relajación corporal, después de la actividad física.\n-\tRealización de juegos con mates elementales (dos torres y rey contra rey, dos alfiles y rey contra rey), en medios físicos, digitales o virtuales.\n-\tRealización de juegos aplicando las normas generales de la apertura.\n-\tJuego de partidas con sus compañeros con anotación algebraica.\n \n ","attitudinal":"-\tPráctica el juego limpio, respetando las reglas de los juegos que realiza.\n-\tValoración y práctica de hábitos de higiene y normas de comportamiento.\n-\tValoración y disfrute de participar en juegos con sus compañeros y compañeras.\n-\tDefensa y respeto por su derecho y el de los y las demás de jugar y realizar actividades físicas.\n-\tReconocimiento de la importancia de la realización de actividades físicas para su desarrollo, bienestar y conservación de la salud.\n-\tCuidado y protección de los ambientes físicos y naturales en donde practica actividades físicas.\n-\tValoración del béisbol como deporte nacional.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.202Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('art-401', 'educacion-artistica', '4to', '{"id":"art-401","name":"Artes Visuales, Dibujo, Pintura y Modelado","themes":[{"id":"t-art-401-1","name":"Color, Forma y Modelado","subthemes":[{"id":"st-art-401-1-1","name":"Teoría del color: colores primarios, secundarios y terciarios"},{"id":"st-art-401-1-2","name":"Uso de formas geométricas y simétricas en creaciones artísticas"},{"id":"st-art-401-1-3","name":"Técnicas básicas de modelado tridimensional con arcilla o plastilina"}]}],"grade_levels":["4to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"art-401-block-1","themes":["Color, Forma y Modelado"],"conceptual":"-\tEl realismo y la ficción en diferentes manifestaciones artísticas.\n-\tLa representación de objetos y personajes imaginarios.\n-\tEl pensamiento divergente como generador de creatividad.\n-\tMúsica y danzas tradicionales dominicanas (merengue y mangulina). \nCaracterísticas musicales, coreográficas y visuales fundamentales.\n-\tIdentidad cultural. Patrimonio material e inmaterial. Bienes culturales.\nArtes Visuales\n-\tEl dibujo (Líneas, luces y sombras como elementos    configuradores de la forma).\n-\tEl círculo cromático: combinaciones y tonalidades del color.\n-\tEl color en los lenguajes visuales: colores primarios, secundarios y complementarios.\n-\tLa narración visual con imágenes fijas o en movimiento.\n-\tTransformaciones reales e imaginarias del espacio (plástico-visual y escénico).\n \n-\tLa exposición de artes visuales y sus componentes básicos: espacio expositivo, iluminación, información del catálogo de participantes, ficha técnica de la obra, entre otros.\n-\tComposiciones visuales en objetos y producciones artísticas bidimensionales (pintura, serigrafía, fotografía, grabado, entre otros) y tridimensionales (cerámicas, maderas talladas, higüeros, pilones, entre otros.).\nArtes Escénicas\n-\tEl tiempo en el movimiento y el gesto corporal.\n-\tRecursos asociados al tiempo \n(velocidad, continuidad y energía), al espacio (niveles bajo, medio y alto) y direcciones, (arriba/abajo, derecha/ izquierda, amplitudes).\n-\tTíteres: figuras animadas para jugar y contar historias.\n-\tAcciones reales e imaginarias para la representación de cuentos breves, pequeñas historias, mitos y leyendas de su región o comunidad.\n-\tLa dramatización de cuentos, poesías y canciones. Personajes teatrales.\n-\tLa representación escénica: textos, personajes tradicionales y pregones.","procedural":"-\tExploración en diferentes manifestaciones artísticas, a partir de temas o formas del realismo y la ficción.\nArtes Visuales\n-\tLa fotografía con dispositivos móviles y sus posibilidades comunicativas.\n-\tCaracterísticas de la fotografía, considerando temáticas y tipos de encuadres.\n-\tLos medios audiovisuales y de las TIC como recursos de realización y análisis de producciones \nartísticas, articulando la percepción, la imaginación y la exploración.\n-\tFormas bidimensionales y tridimensionales pertenecientes a diferentes contextos, géneros y estilos. Técnicas y materiales en el lenguaje plástico-visual.\n-\tUtilización de los colores primarios y secundarios en producciones artísticas a partir de temas de la realidad y de la imaginación.\n-\tEl dibujo a lápiz, a carboncillo y a la témpera en la representación de objetos y personajes imaginarios.\n-\tDiseño y creación de objetos y personajes a partir de simbologías o referentes visuales propios de su región, utilizando materiales de su entorno inmediato.\n \n-\tCreación de dibujos para representar objetos, personas o ambientes rurales y urbanos, a partir del reconocimiento de sus  formas, colores u otras características estéticas.\n-\tAnimaciones sencillas creadas a partir del lenguaje audiovisual: guion, realización, montaje y sonido.\n-\tUtilización del círculo cromático para la representación de emociones y sentimientos en la ejecución de sus producciones visuales.\n-\tRealización de exposiciones de artes visuales y aplicadas. El plan de acción, paso a paso.\nArtes Escénicas\n-\tAcciones físicas y gestos expresivos en relación con los objetos, usos y costumbres de su realidad para comunicar sentimientos, emociones e ideas.\n-\tDramatización de cuentos, poesías y canciones. Interpretación de personajes teatrales.\n-\tModificación del espacio (escénico y plástico visual), utilizando elementos, gestos o movimientos a partir de un concepto real o imaginario.\n-\tEjecución de la mangulina y algunas formas danzadas del merengue dominicano.\n-\tManejo de títeres.\n-\tMontaje de piezas o cuentos breves, con títeres, como medio para conocer, interpretar y transformar la realidad.\n-\tMontaje de espectáculos escénicos integrando distintos elementos artísticos. El plan de acción, paso a paso.\n ","attitudinal":"-\tLa naturalidad en la expresión vocal (hablada o cantada) y corporal, individual y colectiva.\n-\tLa creatividad en el uso de diversos tipos de títeres y otras manifestaciones artísticas, valorando su utilidad a la hora de expresarse.\n-\tLa autoestima en la comunicación artística.\n-\tColaboración, solidaridad y respeto en actividades artísticas colectivas.\n-\tDisfrute de costumbres y prácticas artísticas tradicionales.\n-\tValoración de distintas manifestaciones artísticas, realistas o de ficción.\n-\tValoración y disfrute de los bienes culturales de su comunidad \n(materiales e inmateriales) haciendo conciencia sobre la necesidad de su preservación.\n-\tRespeto a las indicaciones de letreros y gráficos que regulan la convivencia y el orden en entornos rurales y urbanos (parques, monumentos, señalización de tránsito, pasos peatonales, rampas, aceras, depósitos clasificados para desechos, alumbrados).\n \n-\tValoración de los elementos técnicos que enriquecen distintas expresiones \nartísticas (iluminación, banda sonora, amplificación, decoración, maquillaje, vestuarios…).\n-\tValoración de los sentidos, la voz y el cuerpo como propiedades únicas e instrumentos de comunicación y percepción. Respeto a las diferencias.\n-\tValoración de las expresiones propias y ajenas, a partir del respeto y tolerancia con los desacuerdos.\n-\tDisposición a la terminación de la obra artística atendiendo a principios estéticos.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.203Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('art-501', 'educacion-artistica', '5to', '{"id":"art-501","name":"Artes Escénicas, Teatro de Títeres y Pantomima","themes":[{"id":"t-art-501-1","name":"Expresión Gestual, Corporal y Dramática","subthemes":[{"id":"st-art-501-1-1","name":"Improvisación teatral, gestualidad y pantomima"},{"id":"st-art-501-1-2","name":"Elaboración y manejo de títeres y máscaras expresivas"},{"id":"st-art-501-1-3","name":"Representación de pequeños diálogos y dramatizaciones escolares"}]}],"grade_levels":["5to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"art-501-block-1","themes":["Expresión Gestual, Corporal y Dramática"],"conceptual":"\"Artes Escénicas\"\n \n-\tEl títere de guante.\n-\tFormas folklóricas musicales, cantadas, bailadas y teatralizadas.\n-\tJuegos infantiles tradicionales.\n-\tLa pantomima como técnica escénica.\n-\tEscenificaciones folklóricas con títeres y con pantomima de leyendas, rimas y textos del legado cultural dominicano.\n ","procedural":"\"Artes Escénicas\"\n-\tUso del cuerpo y la voz en el manejo de títeres de guante y la pantomima.\n-\tCoordinación, equilibrio y percepción del espacio en la pantomima.\n-\tAplicación de técnicas de manejo de subidas y bajadas de escaleras y manejo de objetos en la pantomima.\n-\tDramatización en teatro de títeres y pantomima: uso de textos con derecho de autor y la adaptación de cuentos, poesías, experiencias personales, sentimientos, recuerdos y canciones.\n-\tUso de máscaras para la representación de personajes.\n-\tInterpretación de formas folklóricas musicales, cantadas, bailadas y teatralizadas como legado cultural dominicano e incorporarlas a producciones artísticas.\n-\tIdentificación de los rasgos de la cultura regional presentes en la obra de artistas escénicos. (incluye lo gastronómico, uso del lenguaje, hábitat, mitos y leyendas).\n-\tEscenificaciones folklóricas y costumbristas (danza, títeres y pantomima): gestualidad y expresión corporal propias.\n ","attitudinal":"-\tValoración y disfrute de las características de las obras pictóricas producidas por artistas nacionales.\n-\tApreciación de instrumentos musicales de uso popular y folklórico (tambora, güira, guitarra, balsié y marimba de cajón).\n-\tValoración de las creaciones de artistas escénicos y su vinculación con las culturas regionales.\n-\tEsmero en la realización de gráficos promoviendo soluciones a problemáticas sociales.\n-\tValoración de la difusión de obras artísticas criollas en montajes, representaciones, exposiciones y muestras artísticas.\n-\tDisfrute de la realización de actividades colectivas que propicien la interacción grupal.\n-\tValoración del trabajo cooperativo en provecho de la armonía grupal en su participación en bandas rítmicas y conjuntos de flauta dulce.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.203Z');
INSERT OR REPLACE INTO custom_units (id, subject_id, grade_id, content, updated_at) VALUES ('art-601', 'educacion-artistica', '6to', '{"id":"art-601","name":"Música, Canto Coral y Folclore Dominicano","themes":[{"id":"t-art-601-1","name":"Ritmo, Tradiciones Musicales e Himnos","subthemes":[{"id":"st-art-601-1-1","name":"Instrumentos folclóricos dominicanos: güira, tambora y acordeón"},{"id":"st-art-601-1-2","name":"Bailes tradicionales y ritmos folclóricos (merengue y sarandunga)"},{"id":"st-art-601-1-3","name":"Canto coral escolar: entonación de himnos y canciones patrióticas"}]}],"grade_levels":["6to"],"subjectId":"educacion-artistica","week_duration":4,"description":"","achievementIndicators":[],"conceptual_content":[{"id":"art-601-block-1","themes":["Ritmo, Tradiciones Musicales e Himnos"],"conceptual":"\"Educación Musical\"\n-\tTécnica vocal para hablar y cantar. Formas de habla de las diferentes regiones del país.\n-\tMúsica folklórica dominicana. Géneros.\n-\tGéneros musicales populares.\n ","procedural":"-\tEducación Musical\n-\tRespiración y técnica vocal para el canto coral.\n-\tInventario y clasificación de ritmos folklóricos dominicanos.\n-\tPráctica de géneros musicales, populares y regionales (vocales, corporales e instrumentales).\n ","attitudinal":"-\tDesarrollo de la interacción grupal y fomento de la imaginación creadora en producciones artísticas.\n-\tApertura a la diversidad de expresiones artísticas populares nacionales.\n "}],"procedural_content":[],"attitudinal_content":[]}', '2026-06-18T02:24:54.203Z');